using Microsoft.VisualStudio.TestTools.UnitTesting;
using WPFUI.Models;
using WPFUI.ViewModels;

namespace TestEngine.ViewModels
{
    [TestClass]
    public class TestGameSession
    {
        private static GameSession CreateGameSession() =>
            new GameSession(new Player("Test Player", "Fighter",
                experience: 0, maximumHitPoints: 10, currentHitPoints: 10, gold: 1000));

        [TestMethod]
        public void TestCreateGameSession()
        {
            GameSession gameSession = CreateGameSession();

            Assert.IsNotNull(gameSession.CurrentPlayer);
            Assert.AreEqual("Home", gameSession.CurrentLocation.Name);
        }

        [TestMethod]
        public void TestPlayerMovesHomeAndIsCompletelyHealedOnKilled()
        {
            GameSession gameSession = CreateGameSession();

            gameSession.MoveNorth();
            Assert.AreEqual("Town square", gameSession.CurrentLocation.Name);

            gameSession.CurrentPlayer.TakeDamage(999);

            Assert.AreEqual("Home", gameSession.CurrentLocation.Name);
            Assert.AreEqual(gameSession.CurrentPlayer.Level * 10, gameSession.CurrentPlayer.CurrentHitPoints);
        }
    }
}

